const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

/**
 * Parse an election from raw standard-input text.
 *
 * Returns `{ candidates, ballots }` where `candidates` is the array of
 * declared names in declaration order and `ballots` is an array of
 * `{ count, names }` objects, `count` being a BigInt.
 *
 * Throws `ElectionError` with the exact message (sans `error: ` prefix) to
 * print on the first invalid line, per the specification.
 */
export function parseElection(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  let candidates = null
  const candidateSet = new Set()
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'candidates') {
      if (candidates !== null) {
        throw new ElectionError(`line ${lineNumber}: candidates must be declared once, before any ballot`)
      }
      const names = tokens.slice(1)
      if (names.length === 0) {
        throw new ElectionError(`line ${lineNumber}: expected candidates <name>...`)
      }
      const seen = new Set()
      for (const name of names) {
        if (!NAME_RE.test(name)) {
          throw new ElectionError(`line ${lineNumber}: invalid candidate name ${name}`)
        }
        if (seen.has(name)) {
          throw new ElectionError(`line ${lineNumber}: candidate ${name} is declared twice`)
        }
        seen.add(name)
      }
      candidates = names
      for (const name of names) candidateSet.add(name)
    } else if (directive === 'ballot') {
      if (candidates === null) {
        throw new ElectionError(`line ${lineNumber}: candidates must be declared once, before any ballot`)
      }
      if (tokens.length < 3) {
        throw new ElectionError(`line ${lineNumber}: expected ballot <count> <candidate>...`)
      }
      const countToken = tokens[1]
      if (!COUNT_RE.test(countToken)) {
        throw new ElectionError(`line ${lineNumber}: count must be a positive integer`)
      }
      const names = tokens.slice(2)
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          throw new ElectionError(`line ${lineNumber}: unknown candidate ${name}`)
        }
        if (seen.has(name)) {
          throw new ElectionError(`line ${lineNumber}: candidate ${name} is repeated`)
        }
        seen.add(name)
      }
      ballots.push({ count: BigInt(countToken), names })
    } else {
      throw new ElectionError(`line ${lineNumber}: unknown directive ${directive}`)
    }
  }

  if (candidates === null) {
    throw new ElectionError('no candidates')
  }

  return { candidates, ballots }
}
"}

