 * Run the instant-runoff count described by the specification.
 *
 * `candidates` is the array of declared names, `ballots` is an array of
 * `{ count, names }` (count a BigInt).
 *
 * Returns `{ rounds, winner }` where `rounds` is an array of round records
 * `{ counts, exhausted, eliminated }`:
 *   - `counts` is an array of `{ name, votes }` (votes a BigInt) for every
 *     candidate continuing at the start of that round, sorted by descending
 *     votes then ascending name.
 *   - `exhausted` is the BigInt count of ballots that counted for nobody.
 *   - `eliminated` is the name eliminated after that round, or `null` when
 *     the round ended the election (by a win or by no active ballots).
 * `winner` is the winning name, or `null` when nobody ever won.
 */
export function runElection(candidates, ballots) {
  let continuing = new Set(candidates)
  const history = []
  const rounds = []
  let winner = null

  for (;;) {
    const votes = new Map()
    for (const name of continuing) votes.set(name, 0n)

    let exhausted = 0n
    for (const ballot of ballots) {
      const choice = ballot.names.find((name) => continuing.has(name))
      if (choice === undefined) {
        exhausted += ballot.count
      } else {
        votes.set(choice, votes.get(choice) + ballot.count)
      }
    }

    history.push(votes)

    let activeTotal = 0n
    for (const v of votes.values()) activeTotal += v

    const counts = [...continuing]
      .map((name) => ({ name, votes: votes.get(name) }))
      .sort((a, b) => {
        if (a.votes !== b.votes) return a.votes < b.votes ? 1 : -1
        return a.name < b.name ? -1 : a.name > b.name ? 1 : 0
      })

    if (activeTotal === 0n) {
      rounds.push({ counts, exhausted, eliminated: null })
      winner = null
      break
    }

    let found = null
    for (const name of continuing) {
      if (votes.get(name) * 2n > activeTotal) {
        found = name
        break
      }
    }

    if (found !== null) {
      rounds.push({ counts, exhausted, eliminated: null })
      winner = found
      break
    }

    let minVotes = null
    for (const v of votes.values()) {
      if (minVotes === null || v < minVotes) minVotes = v
    }
    const tied = [...continuing].filter((name) => votes.get(name) === minVotes)
    const eliminated = breakTie(tied, history)

    rounds.push({ counts, exhausted, eliminated })

    continuing = new Set(continuing)
    continuing.delete(eliminated)
  }

  return { rounds, winner }
}

function breakTie(names, history) {
  let candidates = names.slice()
  if (candidates.length === 1) return candidates[0]

  let r = 0
  while (r < history.length) {
    const votesMap = history[r]
    const values = candidates.map((name) => votesMap.get(name))
    const allEqual = values.every((v) => v === values[0])
    if (!allEqual) {
      let minVal = values[0]
      for (const v of values) if (v < minVal) minVal = v
      candidates = candidates.filter((name) => votesMap.get(name) === minVal)
      if (candidates.length === 1) return candidates[0]
      r = 0
      continue
    }
    r++
  }

  candidates.sort()
  return candidates[candidates.length - 1]
}
"}

