/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { parseElection } from './parser.js'
import { runElection } from './election.js'
import { ElectionError } from './errors.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require('node:fs')
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'rounds' && args[0] !== 'tally')) {
    process.stderr.write('error: usage: cli.js rounds|tally\n')
    process.exit(2)
  }
  const mode = args[0]

  const input = readStdin()

  let election
  try {
    election = parseElection(input)
  } catch (err) {
    if (err instanceof ElectionError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(2)
    }
    throw err
  }

  const { rounds, winner } = runElection(election.candidates, election.ballots)

  const out = []
  if (mode === 'rounds') {
    rounds.forEach((round, i) => {
      const parts = round.counts.map((c) => `${c.name}=${c.votes}`)
      parts.push(`exhausted=${round.exhausted}`)
      out.push(`round ${i + 1}: ${parts.join(' ')}`)
      if (round.eliminated !== null) {
        out.push(`eliminated ${round.eliminated}`)
      }
    })
  } else {
    out.push(`rounds ${rounds.length}`)
  }

  out.push(winner !== null ? `winner ${winner}` : 'no winner')

  process.stdout.write(out.join('\n') + '\n')
  process.exit(0)
}

main()
"}

